    tourAnalyticsAccBody: 'यहाँ दिखता है कि Ope के पूर्वानुमान असल में हुई बात के कितने क़रीब रहे। Ope आमतौर पर मोटे अंदाज़ से शुरू करता है और आपके ढर्रे सीखते-सीखते सटीक होता जाता है। सुधार यहाँ असली प्रतिशत में दिखेगा — संख्या जितनी कम, पूर्वानुमान उतना भरोसेमंद।',
    tourAnalyticsAccTitle: 'पूर्वानुमान सटीकता',
    tourAnalyticsAdsBody: 'अगर आपने प्रबंधन में कोई विज्ञापन अभियान या ख़ास आयोजन चिह्नित किया है, तो Ope उसका फ़ायदा दिखाता है — हर एक ने आपके सामान्य अपेक्षित स्तर से कितने अतिरिक्त ग्राहक लाए। सकारात्मक फ़ायदा मतलब प्रचार काम आया; सपाट नतीजा मतलब शायद वह क़ीमत के लायक़ नहीं था।',
    tourAnalyticsAdsTitle: 'विज्ञापन और आयोजन का असर',
    tourAnalyticsBody: 'यहाँ आपको पूर्वानुमान की सटीकता, व्यस्त घंटों के लिए स्टाफ़ की सिफ़ारिशें, आपके चिह्नित विज्ञापनों या आयोजनों का फ़ायदा, और वफ़ादार नियमित ग्राहकों की लाभप्रदता मिलेगी।',
    tourAnalyticsRegBody: 'यहाँ देख सकते हैं कि आपका हर नियमित ग्राहक कितनी बार आता है और समय के साथ आपके व्यवसाय में कितना योगदान देता है। अगर किसी की आवाजाही घटने लगे, तो Ope उसे चिह्नित कर देता है ताकि आप उसे खोने से पहले संपर्क कर सकें।',
    tourAnalyticsRegTitle: 'आपके वफ़ादार नियमित ग्राहक',
    tourAnalyticsStaffBody: 'आपके व्यस्त घंटों के ढर्रे के आधार पर Ope बताता है कि दिन के हर घंटे कितने कर्मचारी चाहिए। यह भी दिखाता है कि एक व्यक्ति बढ़ाने या घटाने पर कतार का क्या होगा — ताकि आप ठीक-ठीक देख सकें कि एक अतिरिक्त जोड़ी हाथ कब सचमुच फ़र्क़ डालती है।',
