    tourDarkModeBody: 'Ope हल्के और गहरे दोनों रूप में चलता है। बदलने के लिए नीचे का बटन दबाएँ — अभी आज़माएँ! आप कभी भी बदल सकते हैं।',
    tourDarkModeTitle: 'अपना लुक चुनें — डार्क या लाइट?',
    tourDoneBody: 'Ope जितना अधिक आप लॉग करते हैं, उतना स्मार्ट होता है। आज की बिक्री दर्ज करके शुरू करें — फिर कुछ हफ्तों बाद अपना पहला पूर्वानुमान देखने के लिए वापस आएं। आप यह दौरा कभी भी सेटिंग्स से दोबारा देख सकते हैं।',
