    tourForecastBusyBody: 'पूर्वानुमान स्क्रीन पर नीचे स्क्रॉल करें और देखें कि कल के कौन-से घंटे सबसे व्यस्त रहने की उम्मीद है और हर घंटे कितने कर्मचारी चाहिए हो सकते हैं। Ope यह भी दिखाता है कि टीम में एक व्यक्ति का बदलाव ग्राहकों के इंतज़ार पर क्या असर डालेगा — ताकि आप निश्चिंत होकर योजना बना सकें।',
