    tourFriendlyModeBody: 'हाइलाइट किया टॉगल सरल भाषा मोड चालू करता है, जो तकनीकी शब्दों को सरल रोज़मर्रा के शब्दों से बदलता है। अभी आज़माएं — आप इसे कभी भी बंद कर सकते हैं।',
    tourFriendlyModeTitle: 'सरल शब्दावली पसंद करते हैं?',
    tourLogBody: 'यही वह टैब है जिसे आप रोज़ इस्तेमाल करेंगे। हर बिक्री जैसे ही हो, टैप कर दें, या यहाँ दिन के अंत का कुल दर्ज करें। आप जितना ज़्यादा दर्ज करेंगे, Ope उतना ही समझदार होगा।',
    tourLogRegularBody: "किसी वफ़ादार ग्राहक की विज़िट दर्ज करने के लिए बिक्री बटनों के नीचे 'नियमित ग्राहक दर्ज करें' पर टैप करें। आप यह भी जोड़ सकते हैं कि उन्होंने कितना ख़र्च किया — Ope हर नियमित ग्राहक का मूल्य समय के साथ ट्रैक करता है और बताता है अगर कोई काफ़ी दिनों से नहीं आया।",
    tourLogRegularTitle: 'नियमित ग्राहक दर्ज करें',
    tourLogTitle: 'दर्ज करें टैब — आपका रोज़ का काम',
    tourManageBody: '"प्रबंधन" के अंतर्गत आपको आपके उत्पाद, वफादार नियमित ग्राहक, आवर्ती पैटर्न, प्रचार और सेटिंग्स मिलेंगी। यहीं आप Ope को अपने व्यापार के बारे में सिखाते हैं — जितना अधिक जोड़ें, उतना स्मार्ट।',
    tourManageCurrencyBody: 'सेटिंग्स में वह मुद्रा चुनें जिसमें आपका व्यवसाय चलता है। Ope में दिखने वाली हर राशि उसी में होती है — क़ीमतें, नियमित ग्राहकों का ख़र्च, विज्ञापन की लागत।',
    tourManageCurrencyTitle: 'आपकी मुद्रा',
    tourManagePastBody: 'कोई दिन दर्ज करना छूट गया? उसे भरने या पहले दर्ज किए दिन को सुधारने के लिए यहाँ टैप करें। पूरा इतिहास पूर्वानुमान को पैना बनाता है। छूटे हुए एक हफ़्ते को भरना भी Ope की सटीकता में साफ़ फ़र्क़ लाता है।',
    tourManagePastTitle: 'पिछले दिन',
    tourManagePatBody: 'Ope को नियमित घटनाओं के बारे में बताएँ — जैसे हर रविवार स्कूल भ्रमण — और वह उन्हें असामान्य नहीं, अपेक्षित मानेगा। आप Ope को जितने ज़्यादा ढर्रे सिखाएँगे, उसके पूर्वानुमान उतने बेहतर होंगे और झूठे अलर्ट उतने कम।',
    tourManagePatTitle: 'आवर्ती पैटर्न',
    tourManageProdBody: 'यहाँ अपने बेचे जाने वाले उत्पाद जोड़ें या बदलें। शुरू करने के लिए बस नाम और इकाई काफ़ी है। उत्पाद जुड़ते ही Ope माँग और दोबारा मँगाने की ज़रूरत अपने आप देखता रहता है। पूरी ऑर्डर सलाह के लिए आप चाहें तो आपूर्तिकर्ता का समय, स्टॉक की गिनती और टिकने की अवधि भी जोड़ सकते हैं।',
