    tourFinish: 'Начнём!',
    tourForecastBody: 'Как только вы внесёте несколько дней, этот график покажет, насколько загруженным, вероятно, будет каждый день предстоящей недели — чтобы вы могли планировать заранее. Чем больше вы вносите данных, тем точнее прогноз.',
    tourForecastBusyBody: 'Пролистайте экран прогноза вниз, чтобы увидеть, какие часы завтра будут самыми загруженными и сколько людей может понадобиться в каждый час. Ope также покажет, как изменение команды на одного человека скажется на времени ожидания — чтобы планировать уверенно.',
    tourForecastBusyTitle: 'Часы пик и персонал',
    tourForecastTitle: 'Ваш прогноз спроса',
    tourFriendlyModeBody: 'Выделенный переключатель включает режим «Простой язык», который заменяет технические термины (например, «MAPE» или «запас прочности») простыми повседневными словами. Нажмите его сейчас, чтобы попробовать — вы можете выключить его в любое время.',
    tourFriendlyModeTitle: 'Предпочитаете более простые формулировки?',
    tourLogBody: 'Эту вкладку вы будете открывать каждый день. Отмечайте каждую продажу в момент, когда она происходит, или вносите сюда итоги дня. Чем больше вы записываете, тем умнее становится Ope.',
    tourLogRegularBody: 'Нажмите «Записать постоянного клиента» под кнопками продаж, чтобы отметить визит верного клиента. Можно указать, сколько он потратил — Ope отслеживает ценность каждого постоянного клиента со временем и сообщит, если кто-то давно не заходил.',
    tourLogRegularTitle: 'Записать постоянного клиента',
    tourLogTitle: 'Вкладка «Запись» — ваше ежедневное действие',
    tourManageBody: 'В разделе «Управление» вы найдёте свои товары, постоянных клиентов, повторяющиеся паттерны, акции и настройки. Здесь вы обучаете Ope особенностям своего бизнеса — чем больше добавляете, тем умнее он становится.',
    tourManageCurrencyBody: 'В настройках выберите валюту вашего заведения. Все суммы в Ope показываются в ней — цены, траты постоянных клиентов, стоимость рекламы.',
    tourManageCurrencyTitle: 'Ваша валюта',
    tourManagePastBody: 'Забыли записать день? Нажмите здесь, чтобы заполнить его или исправить уже записанный. Полная история делает прогнозы точнее. Даже одна восстановленная неделя заметно улучшает точность Ope.',
    tourManagePastTitle: 'Прошлые дни',
    tourManagePatBody: 'Расскажите Ope о регулярных событиях — например, о школьной экскурсии каждое воскресенье — и он будет считать их ожидаемыми, а не странными. Чем больше закономерностей вы ему объясните, тем лучше прогнозы и тем меньше ложных тревог.',
    tourManagePatTitle: 'Повторяющиеся паттерны',
    tourManageProdBody: 'Здесь добавляйте и изменяйте товары, которые продаёте. Для начала хватит названия и единицы измерения. Как только товар появился, Ope сам следит за спросом и потребностью в заказе. По желанию укажите срок поставки, остаток и срок годности — тогда советы по заказам будут полными.',
    tourManageProdTitle: 'Ваши товары',
    tourManageSimpleLangBody: 'В разделе Управление → Настройки есть переключатель «Простой язык». Включите его, и Ope заменит технические термины — такие как «MAPE», «запас прочности» или «FIFO» — простыми повседневными словами. Отлично, если какая-то подпись кажется незнакомой. Упрощённая версия доступна на английском и иврите. Сам тур тоже использует более простые формулировки, когда этот режим включён.',
    tourManageSimpleLangTitle: 'Режим простого языка',
    tourManageTitle: 'Управление',
    tourNext: 'Далее →',
    tourOrderBody: 'Пролистайте экран прогноза вниз до советов по заказам — Ope точно скажет, что и когда заказать, исходя из сроков поставки и того, как быстро расходится каждый товар.',
    tourOrderTitle: 'Что заказать',
    tourReplayBtn: 'Повторить тур',
    tourReplayDesc: 'Пройдите обзорную экскурсию по Ope заново с начала.',
    tourReplayLabel: 'Обучающий тур',
    tourSaleBody: 'Нажимайте кнопку товара один раз на каждую проданную единицу. Ope запоминает точное время, поэтому график часов пик складывается сам собой в течение дня.',
