    tourAnalyticsAccBody: "Vous voyez ici à quel point les prévisions d'Ope ont collé à la réalité. Ope commence en général approximatif puis s'affine à mesure qu'il apprend vos habitudes. L'amélioration s'affiche en pourcentage réel — plus le chiffre est bas, plus vous pouvez vous fier à la prévision.",
