    tourDoneBody: "Ope devient plus intelligent à mesure que vous enregistrez. Commencez par enregistrer les ventes d'aujourd'hui — puis revenez dans quelques semaines pour voir votre première prévision. Vous pouvez rejouer ce tour à tout moment depuis Paramètres.",
    tourDoneTitle: 'Vous êtes prêt !',
    tourFinish: 'Allons-y !',
    tourForecastBody: "Une fois quelques jours enregistrés, ce graphique montre à quel point chaque jour de la semaine à venir sera probablement chargé — pour que vous puissiez planifier à l'avance. Il devient plus précis à mesure que vous enregistrez.",
    tourForecastBusyBody: "Faites défiler l'écran Prévision pour voir quelles heures de demain devraient être les plus chargées et combien de personnes prévoir à chaque heure. Ope montre aussi l'effet d'une personne en plus ou en moins sur le temps d'attente — de quoi planifier sereinement.",
