    tourLogRegularBody: "Touchez « Enregistrer un habitué » sous les boutons de vente pour noter la visite d'un client fidèle. Vous pouvez indiquer ce qu'il a dépensé — Ope suit la valeur de chaque habitué dans le temps et vous prévient si l'un d'eux n'est pas venu depuis un moment.",
    tourLogRegularTitle: 'Enregistrer un habitué',
