    tourAnalyticsAccBody: 'এখানে দেখা যায় Ope-র পূর্বাভাস আসলে যা ঘটেছে তার কতটা কাছাকাছি ছিল। Ope সাধারণত মোটা দাগে শুরু করে এবং আপনার ধরন শিখতে শিখতে আরও নিখুঁত হয়। উন্নতি এখানে সত্যিকারের শতকরায় দেখবেন — সংখ্যা যত কম, পূর্বাভাসে তত বেশি ভরসা করা যায়।',
