    tourAnalyticsAdsBody: 'ব্যবস্থাপনায় কোনো বিজ্ঞাপন প্রচার বা বিশেষ অনুষ্ঠান চিহ্নিত করে থাকলে Ope তার বাড়তি দেখায় — প্রত্যেকটি আপনার স্বাভাবিক প্রত্যাশিত মাত্রার তুলনায় কত বাড়তি ক্রেতা এনেছে। ধনাত্মক বাড়তি মানে প্রচার কাজে দিয়েছে; সমান ফল মানে সম্ভবত তা মূল্যবান ছিল না।',
    tourAnalyticsAdsTitle: 'বিজ্ঞাপন ও অনুষ্ঠানের প্রভাব',
