    tourAnalyticsRegBody: 'এখানে দেখতে পাবেন আপনার প্রতিটি নিয়মিত ক্রেতা কত ঘন ঘন আসেন এবং সময়ের সঙ্গে আপনার ব্যবসায় কতটা যোগ করেন। কারও আসা কমে গেলে Ope তা চিহ্নিত করে, যাতে তাঁকে হারানোর আগেই যোগাযোগ করতে পারেন।',
