    tourDarkModeBody: 'Ope উজ্জ্বল ও গাঢ় দুই চেহারাতেই চলে। বদলাতে নিচের বোতাম চাপুন — এখনই দেখুন! যেকোনো সময় বদলাতে পারবেন।',
    tourDarkModeTitle: 'আপনার লুক বেছে নিন — গাঢ় নাকি হালকা?',
    tourDoneBody: 'আপনি যত বেশি লগ করবেন Ope তত বুদ্ধিমান হবে। আজকের বিক্রয় রেকর্ড করে শুরু করুন — তারপর কয়েক সপ্তাহ পরে আপনার প্রথম পূর্বাভাস দেখতে ফিরে আসুন। আপনি সেটিংস থেকে যেকোনো সময় এই ট্যুরটি আবার দেখতে পারেন।',
    tourDoneTitle: 'আপনি প্রস্তুত!',
    tourFinish: 'চলুন শুরু করি!',
    tourForecastBody: 'কয়েক দিন লগ করার পর, এই চার্টটি দেখায় আগামী সপ্তাহের প্রতিটি দিন কতটা ব্যস্ত হতে পারে — যাতে আপনি আগে থেকে পরিকল্পনা করতে পারেন। যত বেশি লগ করবেন এটি তত বেশি নির্ভুল হবে।',
    tourForecastBusyBody: 'পূর্বাভাস পর্দায় নিচে নামলে দেখবেন আগামীকাল কোন ঘণ্টাগুলো সবচেয়ে ব্যস্ত হওয়ার কথা এবং প্রতি ঘণ্টায় কতজন কর্মী লাগতে পারে। দলে একজন কমবেশি করলে ক্রেতার অপেক্ষায় কী প্রভাব পড়ে তাও Ope দেখায় — যাতে নিশ্চিন্তে পরিকল্পনা করতে পারেন।',
    tourForecastBusyTitle: 'ব্যস্ত সময় ও কর্মী',
    tourForecastTitle: 'আপনার চাহিদার পূর্বাভাস',
    tourFriendlyModeBody: "হাইলাইট করা টগলটি সহজ ভাষা মোড চালু করে, যা প্রযুক্তিগত শব্দ (যেমন 'MAPE' বা 'নিরাপত্তা বাফার') সহজ প্রতিদিনের শব্দ দিয়ে প্রতিস্থাপন করে। এখনই চেষ্টা করতে চাপুন — আপনি যেকোনো সময় বন্ধ করতে পারেন।",
    tourFriendlyModeTitle: 'সহজ শব্দ পছন্দ করেন?',
    tourLogBody: 'এই ট্যাবটিই আপনি প্রতিদিন ব্যবহার করবেন। প্রতিটি বিক্রি ঘটার সঙ্গে সঙ্গে চাপুন, অথবা এখানে দিনের শেষের মোট লিখুন। যত বেশি লিখবেন, Ope তত বুদ্ধিমান হবে।',
    tourLogRegularBody: "কোনো অনুগত ক্রেতার আগমন লিখতে বিক্রির বোতামগুলোর নিচে 'নিয়মিত ক্রেতা লিখুন'-এ চাপুন। তিনি কত খরচ করেছেন তাও যোগ করতে পারেন — Ope প্রতিটি নিয়মিত ক্রেতার মূল্য সময়ের সঙ্গে রাখে এবং কেউ অনেক দিন না এলে জানিয়ে দেয়।",
    tourLogRegularTitle: 'নিয়মিত গ্রাহক রেকর্ড করুন',
    tourLogTitle: 'লিখুন ট্যাব — আপনার প্রতিদিনের কাজ',
    tourManageBody: 'পরিচালনার অধীনে আপনি পাবেন আপনার পণ্য, বিশ্বস্ত নিয়মিত গ্রাহক, পুনরাবৃত্ত প্যাটার্ন, প্রচার, এবং সেটিংস। এখানেই আপনি Ope-কে আপনার ব্যবসা সম্পর্কে শেখান — যত বেশি যোগ করবেন, এটি তত বুদ্ধিমান হবে।',
    tourManageCurrencyBody: 'সেটিংসে আপনার ব্যবসার মুদ্রা বেছে নিন। Ope-তে দেখানো প্রতিটি অঙ্ক সেটিই ব্যবহার করে — দাম, নিয়মিত ক্রেতার খরচ, বিজ্ঞাপনের খরচ।',
    tourManageCurrencyTitle: 'আপনার মুদ্রা',
    tourManagePastBody: 'কোনো দিন লিখতে ভুলে গেছেন? সেটি পূরণ করতে বা আগে লেখা কোনো দিন সংশোধন করতে এখানে চাপুন। পূর্ণ ইতিহাস পূর্বাভাসকে ধারালো করে। এমনকি এক সপ্তাহের বাদ পড়া দিন পূরণ করলেও Ope-র নির্ভুলতা স্পষ্টভাবে বাড়ে।',
    tourManagePastTitle: 'অতীতের দিন',
    tourManagePatBody: 'Ope-কে নিয়মিত ঘটনার কথা বলুন — যেমন প্রতি রবিবার স্কুলের ভ্রমণ — তাহলে সেগুলো অস্বাভাবিক নয়, প্রত্যাশিত হিসেবেই ধরা হবে। Ope-কে যত বেশি ধরন শেখাবেন, তার পূর্বাভাস তত ভালো হবে এবং ভুল সতর্কতা তত কমবে।',
    tourManagePatTitle: 'পুনরাবৃত্ত প্যাটার্ন',
    tourManageProdBody: 'আপনি যা বিক্রি করেন সেই পণ্য এখানে যোগ বা সম্পাদনা করুন। শুরু করতে কেবল একটি নাম ও একক লাগে। পণ্য যোগ হলেই Ope চাহিদা ও পুনরায় অর্ডারের প্রয়োজন নিজে থেকেই দেখে। পূর্ণ অর্ডার পরামর্শের জন্য চাইলে সরবরাহকারীর সময়, মজুতের সংখ্যা ও মেয়াদও যোগ করতে পারেন।',
    tourManageProdTitle: 'আপনার পণ্য',
    tourManageSimpleLangBody: "পরিচালনা → সেটিংস-এর অধীনে, আপনি একটি 'সহজ ভাষা' টগল পাবেন। এটি চালু করুন এবং Ope প্রযুক্তিগত শব্দ — যেমন 'MAPE', 'নিরাপত্তা বাফার', বা 'FIFO' — সহজ প্রতিদিনের শব্দ দিয়ে প্রতিস্থাপন করে। কোনো লেবেল অপরিচিত মনে হলে দারুণ কাজে দেয়। ইংরেজি ও হিব্রু উভয়ই সহজ সংস্করণ পায়। এই মোড চালু থাকলে ট্যুরও সহজ শব্দ ব্যবহার করে।",
    tourManageSimpleLangTitle: 'সহজ ভাষা মোড',
    tourManageTitle: 'পরিচালনা',
