    tourOrderBody: 'অর্ডারের পরামর্শ দেখতে পূর্বাভাস পর্দায় নিচে নামুন — আপনার সরবরাহের সময় এবং প্রতিটি পণ্য কত দ্রুত বিক্রি হয় তার ভিত্তিতে Ope ঠিক বলে দেয় কী কখন আনতে হবে।',
    tourOrderTitle: 'কী অর্ডার করবেন',
