    teachOpeDesc: 'Tentukan pola yang Anda tahu berulang — seperti karyawisata sekolah setiap Minggu — dan Ope akan memperkirakannya alih-alih menandainya sebagai tidak biasa.',
    teachOpeTitle: 'Ajari Ope dunia Anda',
    telegram: 'Telegram',
    telegramDesc: 'Hubungkan bot Ope untuk mencatat seperti berbicara',
    thisMonth: 'Bulan ini',
    thisWeekForecast: 'Perkiraan minggu ini',
    thisYear: 'Tahun ini',
    thu: 'Kam',
    todayAmount: 'Hari ini: {currency}{amount}',
    todayBadge: 'Hari ini: {currency}{amount}',
    todayLabel: 'hari ini',
    tomorrowHourByHour: 'Besok jam demi jam',
    tomorrowLabel: 'Besok — {day}',
    tourAnalyticsAccBody: 'Di sini terlihat seberapa dekat perkiraan Ope dengan yang benar-benar terjadi. Ope biasanya mulai kasar lalu makin tepat seiring mempelajari pola Anda. Perbaikannya tampil sebagai persentase nyata — makin kecil angkanya, makin bisa Anda andalkan perkiraannya.',
    tourAnalyticsAccTitle: 'Akurasi perkiraan',
    tourAnalyticsAdsBody: 'Jika Anda menandai kampanye iklan atau acara khusus di Kelola, Ope menampilkan kenaikannya — berapa pelanggan tambahan yang dibawa masing-masing dibanding tingkat normal yang diharapkan. Kenaikan positif berarti promosinya berhasil; hasil datar berarti kemungkinan tidak sepadan.',
    tourAnalyticsAdsTitle: 'Dampak iklan & acara',
    tourAnalyticsBody: 'Di sini Anda menemukan ketepatan perkiraan, saran jumlah staf untuk jam sibuk, kenaikan dari iklan atau acara yang Anda tandai, serta profitabilitas pelanggan setia Anda.',
    tourAnalyticsRegBody: 'Di sini Anda bisa melihat seberapa sering tiap pelanggan tetap datang dan seberapa besar sumbangannya bagi usaha Anda dari waktu ke waktu. Jika kunjungan seseorang mulai menurun, Ope menandainya agar Anda bisa menghubunginya sebelum kehilangan dia.',
    tourAnalyticsRegTitle: 'Pelanggan setia Anda',
    tourAnalyticsStaffBody: 'Berdasarkan pola jam sibuk Anda, Ope memberi tahu berapa staf yang dibutuhkan tiap jam. Ope juga menunjukkan apa yang terjadi pada antrean bila Anda menambah atau mengurangi satu orang — sehingga Anda tahu persis kapan sepasang tangan tambahan benar-benar berpengaruh.',
    tourAnalyticsStaffTitle: 'Saran jumlah staf',
    tourAnalyticsTitle: 'Analisis — pahami pola Anda',
    tourBack: '← Kembali',
    tourDarkModeBody: 'Ope bekerja dalam mode terang maupun gelap. Pakai tombol di bawah untuk berganti — coba sekarang! Bisa diubah kapan saja.',
    tourDarkModeTitle: 'Pilih tampilan Anda — gelap atau terang?',
    tourDoneBody: 'Ope semakin pintar seiring Anda mencatat. Mulailah dengan mencatat penjualan hari ini — lalu kembali lagi dalam beberapa minggu untuk melihat perkiraan pertama Anda. Anda bisa memutar ulang tur ini kapan saja dari Pengaturan.',
    tourDoneTitle: 'Anda sudah siap!',
    tourFinish: 'Ayo mulai!',
    tourForecastBody: 'Setelah Anda mencatat beberapa hari, grafik ini menunjukkan seberapa ramai setiap hari di minggu mendatang kemungkinan akan terjadi — sehingga Anda bisa merencanakan lebih awal. Semakin banyak Anda mencatat, semakin akurat hasilnya.',
    tourForecastBusyBody: 'Gulir ke bawah di layar Perkiraan untuk melihat jam mana besok yang diperkirakan paling ramai dan berapa staf yang mungkin Anda perlukan tiap jam. Ope juga menunjukkan dampak menambah atau mengurangi satu orang terhadap waktu tunggu pelanggan — agar Anda bisa menjadwal dengan mantap.',
    tourForecastBusyTitle: 'Jam sibuk & staf',
    tourForecastTitle: 'Perkiraan permintaan Anda',
    tourFriendlyModeBody: "Sakelar yang disorot mengaktifkan mode Bahasa sederhana, yang mengganti istilah teknis (seperti 'MAPE' atau 'stok pengaman') dengan kata-kata sehari-hari yang sederhana. Tekan sekarang untuk mencoba — Anda bisa menonaktifkannya kapan saja.",
    tourFriendlyModeTitle: 'Lebih suka bahasa yang lebih sederhana?',
    tourLogBody: 'Inilah tab yang akan Anda pakai setiap hari. Ketuk tiap penjualan saat terjadi, atau catat total akhir hari di sini. Makin banyak yang Anda catat, makin cerdas Ope.',
    tourLogRegularBody: "Ketuk 'Catat pelanggan tetap' di bawah tombol penjualan untuk mencatat kunjungan pelanggan setia. Anda bisa menambahkan berapa yang dibelanjakan — Ope melacak nilai tiap pelanggan tetap dari waktu ke waktu dan memberi tahu bila ada yang lama tak datang.",
    tourLogRegularTitle: 'Catat Pelanggan Tetap',
    tourLogTitle: 'Tab Catat — tindakan harian Anda',
    tourManageBody: 'Di bawah Kelola Anda akan menemukan produk, pelanggan tetap setia, pola berulang, promo, dan pengaturan. Di sinilah Anda mengajarkan Ope tentang bisnis Anda — semakin banyak Anda tambahkan, semakin pintar Ope jadinya.',
    tourManageCurrencyBody: 'Di Pengaturan, pilih mata uang yang dipakai usaha Anda. Semua jumlah yang Ope tampilkan memakainya — harga, belanja pelanggan tetap, biaya iklan.',
    tourManageCurrencyTitle: 'Mata uang Anda',
    tourManagePastBody: 'Lupa mencatat satu hari? Ketuk di sini untuk mengisinya atau memperbaiki hari yang sudah tercatat. Riwayat yang lengkap membuat perkiraan lebih tajam. Mengisi satu minggu yang terlewat saja sudah terasa meningkatkan ketepatan Ope.',
    tourManagePastTitle: 'Hari Sebelumnya',
    tourManagePatBody: 'Beri tahu Ope tentang kejadian rutin — misalnya kunjungan sekolah tiap Minggu — dan Ope akan menganggapnya wajar, bukan hari aneh. Makin banyak pola yang Anda ajarkan, makin baik perkiraannya dan makin sedikit peringatan palsu yang Anda terima.',
    tourManagePatTitle: 'Pola Berulang',
    tourManageProdBody: 'Tambah atau ubah produk yang Anda jual di sini. Cukup nama dan satuan untuk memulai. Begitu produk ada, Ope melacak permintaan dan kebutuhan pemesanan secara otomatis. Anda juga bisa menambahkan waktu tunggu pemasok, jumlah stok, dan masa simpan untuk saran pemesanan yang lengkap.',
    tourManageProdTitle: 'Produk Anda',
    tourManageSimpleLangBody: "Di bawah Kelola → Pengaturan, Anda akan menemukan sakelar 'Bahasa sederhana'. Aktifkan dan Ope akan mengganti istilah teknis — seperti 'MAPE', 'stok pengaman', atau 'FIFO' — dengan kata-kata sehari-hari yang sederhana. Cocok jika ada label yang terasa asing. Baik Inggris maupun Ibrani mendapatkan versi sederhana. Tur ini sendiri juga menggunakan bahasa yang lebih sederhana saat mode ini aktif.",
    tourManageSimpleLangTitle: 'Mode bahasa sederhana',
    tourManageTitle: 'Kelola',
    tourNext: 'Lanjut →',
    tourOrderBody: 'Gulir ke bawah di layar Perkiraan untuk melihat saran pemesanan — Ope memberi tahu persis apa yang perlu dipesan dan kapan, berdasarkan waktu tunggu Anda dan seberapa cepat tiap produk terjual.',
    tourOrderTitle: 'Apa yang perlu dipesan',
    tourReplayBtn: 'Putar ulang tur',
    tourReplayDesc: 'Lihat lagi panduan Ope dari awal.',
    tourReplayLabel: 'Tur berpandu',
    tourSaleBody: 'Ketuk tombol produk sekali untuk tiap barang yang terjual. Ope menyimpan waktu persisnya, jadi grafik jam sibuk Anda terbentuk sendiri sepanjang hari.',
    tourSaleTitle: 'Ketuk untuk mencatat penjualan',
    tourSectionPreferences: 'Preferensi',
