    tourSkipStep: 'Lewati langkah ini',
    tourWelcomeBody: 'Ope membantu Anda mengetahui seberapa sibuk bisnis Anda nantinya — sehingga Anda bisa memesan stok yang tepat, menjadwalkan staf yang tepat, dan tidak pernah terkejut. Mari kita lihat sekilas apa saja yang ada di sini.',
