    todayLabel: 'heute',
    tomorrowHourByHour: 'Morgen Stunde für Stunde',
    tomorrowLabel: 'Morgen — {day}',
    tourAnalyticsAccBody: 'Hier sehen Sie, wie nah Opes Prognosen an dem lagen, was wirklich passiert ist. Ope startet meist grob und wird treffsicherer, während es Ihre Muster lernt. Die Verbesserung steht hier als echter Prozentwert — je kleiner die Zahl, desto mehr können Sie sich auf die Prognose verlassen.',
    tourAnalyticsAccTitle: 'Prognosegenauigkeit',
    tourAnalyticsAdsBody: 'Wenn Sie unter Verwalten Anzeigenkampagnen oder besondere Veranstaltungen markiert haben, zeigt Ope deren Zuwachs — wie viele Kunden jede über Ihr normal erwartetes Niveau hinaus gebracht hat. Ein positiver Zuwachs heißt, die Aktion hat gewirkt; ein flaches Ergebnis, dass sie sich wohl nicht gelohnt hat.',
    tourAnalyticsAdsTitle: 'Wirkung von Anzeigen und Veranstaltungen',
    tourAnalyticsBody: 'Hier finden Sie die Prognosegenauigkeit, Personalempfehlungen für Ihre Stoßzeiten, den Zuwachs aus markierten Anzeigen oder Veranstaltungen und die Rentabilität Ihrer Stammkunden.',
    tourAnalyticsRegBody: 'Hier sehen Sie, wie oft jeder Stammkunde kommt und wie viel er über die Zeit zu Ihrem Betrieb beiträgt. Lassen die Besuche eines Stammkunden nach, weist Ope Sie darauf hin, damit Sie sich melden können, bevor Sie ihn verlieren.',
    tourAnalyticsRegTitle: 'Ihre treuen Stammkunden',
    tourAnalyticsStaffBody: 'Anhand Ihrer Stoßzeiten sagt Ope Ihnen, wie viele Leute Sie zu jeder Tagesstunde brauchen. Es zeigt außerdem, was mit der Schlange passiert, wenn Sie eine Person hinzunehmen oder abziehen — so sehen Sie genau, wann ein zusätzliches Paar Hände wirklich etwas bringt.',
    tourAnalyticsStaffTitle: 'Personalempfehlungen',
    tourAnalyticsTitle: 'Auswertungen — Ihre Muster verstehen',
    tourBack: '← Zurück',
    tourDarkModeBody: 'Ope funktioniert hell wie dunkel. Mit der Schaltfläche unten wechseln Sie — probieren Sie es aus! Sie können es jederzeit ändern.',
    tourDarkModeTitle: 'Wählen Sie Ihren Look — dunkel oder hell?',
    tourDoneBody: 'Ope wird umso klüger, je mehr Sie erfassen. Beginnen Sie damit, die heutigen Verkäufe zu erfassen — schauen Sie dann in ein paar Wochen wieder vorbei, um Ihre erste Prognose zu sehen. Sie können diese Tour jederzeit über die Einstellungen erneut abspielen.',
    tourDoneTitle: 'Sie sind startklar!',
    tourFinish: "Los geht's!",
    tourForecastBody: 'Sobald Sie ein paar Tage erfasst haben, zeigt dieses Diagramm, wie geschäftig jeder Tag der kommenden Woche voraussichtlich sein wird — damit Sie im Voraus planen können. Es wird umso genauer, je mehr Sie erfassen.',
    tourForecastBusyBody: 'Scrollen Sie im Prognose-Bildschirm nach unten, um zu sehen, welche Stunden morgen am vollsten werden und wie viele Leute Sie zu welcher Stunde brauchen könnten. Ope zeigt auch, wie sich eine Person mehr oder weniger auf die Wartezeit auswirkt — damit Sie sicher planen können.',
    tourForecastBusyTitle: 'Stoßzeiten und Personal',
    tourForecastTitle: 'Ihre Bedarfsprognose',
    tourFriendlyModeBody: 'Der hervorgehobene Schalter aktiviert den Modus Einfache Sprache, der Fachbegriffe (wie „MAPE" oder „Sicherheitspuffer") durch einfache Alltagswörter ersetzt. Drücken Sie ihn jetzt, um es auszuprobieren — Sie können ihn jederzeit wieder ausschalten.',
    tourFriendlyModeTitle: 'Bevorzugen Sie einfachere Formulierungen?',
    tourLogBody: 'Diesen Reiter benutzen Sie jeden Tag. Erfassen Sie jeden Verkauf, während er passiert, oder tragen Sie hier Ihre Tagesendsummen ein. Je mehr Sie erfassen, desto klüger wird Ope.',
    tourLogRegularBody: 'Tippen Sie unter den Verkaufsknöpfen auf „Stammkunde erfassen“, um den Besuch eines treuen Kunden festzuhalten. Sie können angeben, wie viel er ausgegeben hat — Ope verfolgt den Wert jedes Stammkunden über die Zeit und sagt Ihnen, wenn einer länger nicht da war.',
    tourLogRegularTitle: 'Stammkunden erfassen',
    tourLogTitle: 'Reiter Erfassen — Ihr täglicher Handgriff',
    tourManageBody: 'Unter Verwalten finden Sie Ihre Produkte, treue Stammkunden, wiederkehrende Muster, Aktionen und Einstellungen. Hier bringen Sie Ope Ihr Geschäft bei — je mehr Sie hinzufügen, desto klüger wird es.',
    tourManageCurrencyBody: 'Wählen Sie in den Einstellungen die Währung Ihres Betriebs. Jeder Betrag in Ope nutzt sie — Preise, was Ihre Stammkunden ausgeben, was eine Anzeige gekostet hat.',
    tourManageCurrencyTitle: 'Ihre Währung',
    tourManagePastBody: 'Einen Tag vergessen zu erfassen? Tippen Sie hier, um ihn nachzutragen oder einen bereits erfassten Tag zu korrigieren. Eine vollständige Historie schärft die Prognosen. Schon eine nachgetragene Woche verbessert Opes Treffsicherheit spürbar.',
    tourManagePastTitle: 'Vergangene Tage',
    tourManagePatBody: 'Erzählen Sie Ope von wiederkehrenden Ereignissen — etwa einem Schulausflug jeden Sonntag — und es behandelt sie als erwartet statt als ungewöhnlich. Je mehr Muster Sie Ope beibringen, desto besser die Prognosen und desto weniger Fehlalarme.',
    tourManagePatTitle: 'Wiederkehrende Muster',
    tourManageProdBody: 'Legen Sie hier die Produkte an, die Sie verkaufen, oder bearbeiten Sie sie. Ein Name und eine Einheit reichen zum Start. Sobald ein Produkt existiert, verfolgt Ope Nachfrage und Bestellbedarf automatisch. Optional können Sie Lieferzeit, Bestand und Haltbarkeit ergänzen, für vollständige Bestellempfehlungen.',
    tourManageProdTitle: 'Ihre Produkte',
    tourManageSimpleLangBody: 'Unter Verwalten → Einstellungen finden Sie einen Schalter „Einfache Sprache". Schalten Sie ihn ein, und Ope ersetzt Fachbegriffe — wie „MAPE", „Sicherheitspuffer" oder „FIFO" — durch einfache Alltagswörter. Praktisch, wenn Ihnen ein Begriff unbekannt vorkommt. Sowohl Englisch als auch Hebräisch erhalten die einfache Version. Die Tour selbst nutzt bei aktiviertem Modus ebenfalls die einfachere Formulierung.',
    tourManageSimpleLangTitle: 'Modus Einfache Sprache',
    tourManageTitle: 'Verwalten',
    tourNext: 'Weiter →',
    tourOrderBody: 'Scrollen Sie im Prognose-Bildschirm nach unten zu den Bestellempfehlungen — Ope sagt Ihnen genau, was wann zu bestellen ist, anhand Ihrer Lieferzeiten und wie schnell sich jedes Produkt verkauft.',
    tourOrderTitle: 'Was zu bestellen ist',
    tourReplayBtn: 'Tour wiederholen',
    tourReplayDesc: 'Sehen Sie sich die geführte Tour durch Ope noch einmal von vorn an.',
    tourReplayLabel: 'Geführte Tour',
    tourSaleBody: 'Tippen Sie die Produktknöpfe einmal pro verkauftem Artikel an. Ope merkt sich die genaue Uhrzeit, sodass Ihre Stoßzeiten-Grafik sich im Lauf des Tages von selbst aufbaut.',
    tourSaleTitle: 'Zum Erfassen eines Verkaufs tippen',
    tourSectionPreferences: 'Präferenzen',
    tourSkipAll: 'Tour überspringen',
    tourSkipSection: '{section} überspringen',
    tourSkipStep: 'Diesen Schritt überspringen',
    tourWelcomeBody: 'Ope hilft Ihnen zu wissen, wie geschäftig Ihr Betrieb sein wird — damit Sie den richtigen Bestand bestellen, das richtige Personal einplanen und nie überrascht werden. Machen wir eine kurze Tour durch das, was hier ist.',
